from htmlkit import native
JD = os.path.join(HERE, "out")
UNIT_ZH, UNIT_EN = "權重共享與轉換不變性", "Weight sharing and transformation invariance"
TITLE_ZH = "圖型識別 第四章 KP12：權重共享與轉換不變性（大三）"; TITLE_EN = "Pattern Recognition, Chapter 4, KP12: weight sharing and transformation invariance (undergraduate)"
NOTE_ZH = "教材程度：大學三年級（undergrad）。依講義 lec05-kp12 以 view-from-text-v3 製作：先規劃頁面，每頁以一張原生資訊圖（HTML 設計後轉成原生節點）為主，名詞在同一頁圖內定義。共 9 頁，本單元為自主學習，課堂不講授；所有數字皆由程式計算。"
NOTE_EN = "Level: undergraduate (year 3). Made from the lecture lec05-kp12 with view-from-text-v3: pages were planned first and each page is mainly one native infographic (designed in HTML and converted to native nodes), with the terms defined on the same page. 9 pages; this unit is self-study and is not taught in class; every number is computed by program."
def fig(n, alt_zh, alt_en):
    return lambda: native(f"kp12_p{n}", f"lec05-kp12-p{n}", KP.W, KP.H, JD, alt_en if os.environ.get("KP_LANG") == "en" else alt_zh)
P = []
NXT = {1: ("特徵圖與等變", "the feature maps and equivariance"), 2: ("參數計數", "the parameter count"), 3: ("共享權重的更新", "updating the shared weight"), 4: ("三條不變性路線", "the three routes to invariance"), 5: ("像素乘積的幾何共享", "geometric sharing of pixel products"), 6: ("平方項特例", "the square-term case"), 7: ("小練習", "the exercises"), 8: ("精確式與邊界", "the exact formula and boundaries")}
PREV = {2: ("局部共享規則", "the local sharing rule"), 3: ("特徵圖與等變", "the feature maps and equivariance"), 4: ("參數計數", "the parameter count"), 5: ("共享權重的更新", "updating the shared weight"), 6: ("三條不變性路線", "the three routes to invariance"), 7: ("像素乘積的幾何共享", "geometric sharing of pixel products"), 8: ("平方項特例", "the square-term case"), 9: ("小練習", "the exercises")}
def add(n, lab, title, bridge, notes, alt):
    zh, en = notes
    if n in PREV: zh = f"承接上一頁的「{PREV[n][0]}」。" + zh; en = f"Following the previous page on {PREV[n][1]}. " + en
    if n == 9: zh += "到這裡這個單元就結束了；之後請接著讀下一單元。"; en += " That ends this unit; next, move on to the next unit."
    if n in NXT: zh += f"接下來的下一頁是「{NXT[n][0]}」。"; en += f" Next, the next page covers {NXT[n][1]}."
    P.append(dict(lab=lab, title=title, bridge=bridge, notes=(zh, en), layout="freeform", spec=fig(n, *alt)))
add(1, ("局部共享規則", "Local sharing"),
    ("局部共享規則：每個視窗只看一小塊，所有位置用同一組權重，3×3 視窗的分數 1 + 1 + 1 = 3", "Local sharing: each window sees a small patch, all positions share weights, and a 3×3 window scores 3"),
    ("希望同一個物件移動後仍屬同類，是不是要網路裡每個數字都不變？", "We want the same object to stay in its class after it moves. Must every number in the network stay the same?"),
    ("這是 KP12 的第一頁，這個單元是自主學習。先備三件事：加權計分與偏置（KP06）、鏈鎖法則（KP06）、用第 i 列第 j 欄指出陣列中的一格。希望同一個物件移動後仍屬同類，不等於要求網路裡每個數字都不變。做法是兩步：先限制每個單元只看一小塊範圍，也就是 3×3 的視窗，叫感受野；再讓所有位置用同一組權重，叫權重共享。設定：6×6 影像，只有一條三格直筆畫，在第 1 欄、第 1 至 3 列；向右平移兩欄得到 Tx，筆畫在第 3 欄；視窗每次移一格、不補邊，共 4 乘 4 等於 16 個位置。共享核 K 的中間欄為 1，圖中視窗的分數是 1 加 1 加 1 等於 3（程式計算）。",
     "This is the first page of KP12, a self-study unit. Prerequisites: weighted scoring with a bias (KP06), the chain rule (KP06), and using row i, column j to point at one cell of an array. We want the same object to stay in its class after it moves, which does not mean every number in the network must stay the same. The method has two steps: first restrict each unit to a small patch, a 3×3 window called the receptive field; then let every position use the same set of weights, called weight sharing. Setup: a 6×6 image with a single three-cell vertical stroke in column 1, rows 1 to 3; shifting it two columns right gives Tx with the stroke in column 3; the window moves one cell at a time with no padding, giving 4 times 4, that is 16 positions. The shared kernel K has ones in its middle column and the window in the figure scores 1 plus 1 plus 1, which is 3 (computed by program)."),
    ("Left: a 6×6 image with a three-cell stroke in column 1 (a 3×3 window framed) and the same stroke shifted two columns right; right: the shared 3×3 kernel with ones in its middle column and the window score 1+1+1=3.",) * 2)
add(2, ("特徵圖與等變", "Feature maps"),
    ("特徵圖與等變：F(x) 的亮處在第 0 欄、F(Tx) 在第 2 欄；取最大值，z 都是 3", "Feature maps: F(x) is bright in column 0, F(Tx) in column 2, and max pooling gives z = 3 for both"),
    ("局部共享規則：所有位置用同一組權重，3×3 視窗的分數是 3。把這個核滑過整張影像，得到的是什麼？平移後又怎麼變？", "The local sharing rule: every position uses the same weights and a 3×3 window scores 3. What do we get by sliding this kernel over the whole image, and how does it change after the shift?"),
    ("這一頁把核滑過整張影像。特徵圖是把每個視窗的分數依位置排成陣列，記為 F(x)，本例 4×4。逐格算出 F(x) 的第 0 欄是 2、3、2、1，其餘為 0；F(Tx) 的第 2 欄是 2、3、2、1。第 0 欄的 2、3、2、1 來自視窗列範圍與筆畫列 1 至 3 的重疊格數。平移等變性是輸入平移，輸出也按對應方式平移，F(Tx) 等於 T F(x)。最大值彙整只取最大值 z 等於 max F(x)，平移前後都是 3：反應跟著筆畫移動是等變，讀出不隨位置改變是不變。限制：整數平移、步長、補邊與邊界必須相容；彙整會丟掉位置（程式計算）。",
     "This page slides the kernel over the whole image. A feature map arranges the window scores by position, written F(x), 4×4 here. Computed cell by cell, column 0 of F(x) is 2, 3, 2, 1 and the rest are 0; column 2 of F(Tx) is 2, 3, 2, 1. The 2, 3, 2, 1 come from how many cells the window rows overlap with stroke rows 1 to 3. Translation equivariance means that shifting the input shifts the output correspondingly, F(Tx) equals T F(x). Global max pooling keeps only the maximum, z equal to max F(x), which is 3 before and after the shift: a response that moves with the stroke is equivariant and a read-out that does not depend on position is invariant. Limits: integer shifts, stride, padding and boundaries must agree, and pooling discards position (computed by program)."),
    ("Two 4×4 feature maps: F(x) has 2,3,2,1 in column 0 and F(Tx) the same numbers in column 2; global max pooling gives z=3 for both.",) * 2)
add(3, ("參數計數", "Parameter count"),
    ("共享把 160 個參數降到 10 個：16 個位置 × (9 + 1) 對 9 + 1", "Sharing cuts 160 parameters to 10: 16 positions × (9 + 1) against 9 + 1"),
    ("F(x) 的亮處在第 0 欄、F(Tx) 在第 2 欄，最大值都是 3。共享到底省了多少參數？", "The bright part of F(x) is in column 0 and of F(Tx) in column 2, with maximum 3 for both. How many parameters does sharing really save?"),
    ("這一頁數參數。不共享：16 個位置，各有 9 個權重與 1 個偏置，16 乘 (9 加 1) 等於 160。共享：所有位置共用 9 個權重與 1 個偏置，9 加 1 等於 10。共享省下的是可獨立調整的數字，不是取消各位置的計算：十六個位置仍然都要算一次。這個減量需要共享假設適合任務；參數少不代表每個問題都更準，也不代表運算次數只剩十分之一（程式計算）。",
     "This page counts parameters. Without sharing: 16 positions, each with 9 weights and 1 bias, 16 times (9 plus 1) equals 160. With sharing: all positions share 9 weights and 1 bias, 9 plus 1 equals 10. What sharing saves is the number of independently adjustable values, not the computation at each position: all sixteen positions are still computed once. The saving requires that the sharing assumption suits the task; fewer parameters do not mean more accuracy on every problem, nor that the number of operations falls to a tenth (computed by program)."),
    ("Left: sixteen positions with 10 parameters each, 16×(9+1)=160; right: all positions share one set, 9+1=10.",) * 2)
add(4, ("共享權重的更新", "Shared update"),
    ("共享權重 k 的梯度是各位置貢獻的總和：0.2×3 + (−0.1)×1 = 0.5，更新後 k = 0.95", "The shared weight's gradient sums the positions: 0.2×3 + (−0.1)×1 = 0.5, so k becomes 0.95"),
    ("共享把 160 個參數降到 10 個，從 16 個位置 × (9 + 1) 變成 9 + 1。訓練時，共享的權重怎麼更新？", "Sharing cuts 160 parameters to 10, and sharing really saves them. How is the shared weight updated in training?"),
    ("這一頁看共享權重怎麼更新，一步一步來。設共享的某個權重為 k；位置 p 的分數是 rp，乘上 k 的輸入是 xp，所以局部線性時 rp 對 k 的偏導是 xp。令 δp 等於 J 對 rp 的偏導，鏈鎖法則把所有路徑加起來：J 對 k 的偏導等於各位置 δp 乘 xp 的總和。數值例子：兩個位置給出 0.2 乘 3 與負 0.1 乘 1，總梯度 0.6 減 0.1 等於 0.5。學習率 η 等於 0.1、原 k 等於 1 時，更新為 k 等於 1 減 0.1 乘 0.5 等於 0.95，所有位置接著都用 0.95。活化函數的導數已含在 δ 之內，不應漏掉或重算（程式計算）。",
     "This page shows how the shared weight is updated, step by step. Let one shared weight be k; the score at position p is rp and the input multiplied by k is xp, so with local linear scoring the derivative of rp with respect to k is xp. Let δp equal the derivative of J with respect to rp; the chain rule adds up all paths: the derivative of J with respect to k equals the sum over positions of δp times xp. Numerical example: two positions give 0.2 times 3 and minus 0.1 times 1, a total gradient of 0.6 minus 0.1 equal to 0.5. With learning rate η equal to 0.1 and old k equal to 1 the update is k equal to 1 minus 0.1 times 0.5, which is 0.95, and every position then uses 0.95. The derivative of an activation is already inside δ and must be neither dropped nor repeated (computed by program)."),
    ("Shared gradient dJ/dk = sum_p delta_p x_p with two positions 0.2*3=0.6 and -0.1*1=-0.1, total 0.5; update k = 1 - 0.1*0.5 = 0.95.",) * 2)
add(5, ("三條不變性路線", "Three routes"),
    ("不變性有三條路線：選不變特徵、架構約束、資料擴增，各有各的風險", "Three routes to invariance: invariant features, architectural constraints, data augmentation"),
    ("共享權重 k 的梯度是各位置貢獻的總和，更新後 k = 0.95。讓分類對平移不變，除了共享，還有哪些路線？", "The gradient of the shared weight k is the sum of the positions' contributions and k becomes 0.95. Besides sharing, which routes make a classification invariant to shifts?"),
    ("這一頁把不變性的三條路線放在一起比較。局部共享只是其中一種架構先驗，實際系統可以結合三種，但要先判斷變換是否保留類別。選不變特徵：先把資料轉成對指定變換不敏感的表示，風險是可能丟掉辨識所需的資訊。架構約束：共享權重加上適當彙整，明確限制哪些計算必須相同，風險是只對相容的變換成立。資料擴增：用合理的變換產生更多訓練例子，風險是有限例子通常不保證所有變換下都不變。",
     "This page compares the three routes to invariance. Local sharing is only one architectural prior; real systems can combine the three, but first decide whether the transformation preserves the class. Choosing invariant features: first turn the data into a representation insensitive to the given transformation; the risk is losing information needed for recognition. Architectural constraints: shared weights plus a suitable pooling explicitly force some computations to be identical; the risk is that it holds only for compatible transformations. Data augmentation: generate more training examples with reasonable transformations; the risk is that finite examples usually do not guarantee invariance under every transformation."),
    ("Three columns: choose invariant features (risk: lose information), architectural constraints (risk: only compatible transformations), data augmentation (risk: no guarantee for all transformations).",) * 2)
add(6, ("像素乘積的幾何共享", "Geometric sharing"),
    ("像素乘積的幾何共享：平移保留位移向量，旋轉保留長度，位移相同或長度相同的像素對可共用係數", "Pairs with equal displacement (translation) or equal length (rotation) can share a coefficient"),
    ("不變性的三條路線：選不變特徵、架構約束、資料擴增。把兩個像素相乘，哪些像素對可以共用係數？", "Invariance has three routes: invariant features, architectural constraints and data augmentation. If two pixels are multiplied, which pixel pairs can share a coefficient?"),
    ("這一頁看高階輸入乘積中的幾何共享。高階網路的分數包含輸入乘積，例如 v 等於 b 加上 ai xi 的總和再加上 cjk xj xk 的總和，再經活化 f(v)。兩個像素相乘會讓一對位置的幾何關係進入模型。平移時，兩端點同時加位移 t，差向量不變：(pk 加 t) 減 (pj 加 t) 等於 pk 減 pj，所以能共用係數的是位移向量相同的像素對；左圖兩條藍線位移都是 (1,1) 可共享，橘線位移 (2,2)，斜率相同卻不能共用，所以同斜率就夠過於粗略。旋轉保留線段長度，因此 (1,0) 與 (0,1) 的長度都是 1，可讓相同長度的像素對共用二階係數。在有限像素網格上，任意角度旋轉常需插值或裁切；只有相容的轉換、項與彙整，才可能得到精確不變性。",
     "This page looks at geometric sharing in higher-order input products. The score of a higher-order network contains input products, for example v equal to b plus the sum of ai xi plus the sum of cjk xj xk, then an activation f(v). Multiplying two pixels brings the geometric relation of a pair of positions into the model. Under translation both endpoints move by t and the difference vector stays: (pk plus t) minus (pj plus t) equals pk minus pj, so the pairs that can share a coefficient are those with the same displacement vector; in the left chart both blue lines have displacement (1,1) and can share, while the orange line has displacement (2,2): same slope but no sharing, so same slope is too crude a condition. Rotation preserves segment length, so (1,0) and (0,1) both have length 1, and pairs of equal length can share a second-order coefficient. On a finite pixel grid an arbitrary rotation often needs interpolation or cropping, and exact invariance needs compatible transformations, terms and pooling."),
    ("Left: pixel pairs on a grid, two blue lines with displacement (1,1) that can share and an orange line with displacement (2,2); right: unit vectors (1,0) and (0,1) on a circle, both of length 1.",) * 2)
add(7, ("平方項特例", "Square-term case"),
    ("平方項特例：平方和對旋轉不變，但線性項讓 (1,0) 與 (0,1) 的分數不同，一個項對稱不代表整體對稱", "The sum of squares is rotation invariant, but the linear term makes (1,0) and (0,1) score differently"),
    ("位移相同的像素對可共享，長度相同的像素對可共享。特殊的平方和只需多一個係數，整體模型就對稱了嗎？", "Pixel pairs with equal displacement can share, and so can pairs of equal length. A special sum of squares needs only one more coefficient; is the whole model then symmetric?"),
    ("這一頁看平方項特例。模型 v 等於 b 加 ai xi 的總和再加 c 乘所有 xi 平方的總和；c 是所有平方項共同的係數，比原來只多一個參數，而不是每格各加一個。平方和就是 x 的範數平方：(1,0) 與 (0,1) 都得 1 平方加 0 平方等於 1，所以平方和本身對正交旋轉不變。但線性項可能不同：若 a 等於 (1,0)，兩點的分數分別為 b 加 1 加 c 與 b 加 c，不相等。歷史架構：來源描述三個隱藏層，前兩層由特徵圖組成；每個單元只接收前一層的局部視窗，同一張圖上的對應連線共用權重。這與本例的三格筆畫是同一個共享原理，但不是同一個架構；沒有足夠的原始細節，不能推算其完整參數數或準確率（程式計算）。",
     "This page looks at the square-term special case. The model v equals b plus the sum of ai xi plus c times the sum of all xi squared; c is one coefficient shared by all square terms, one extra parameter rather than one per cell. The sum of squares is the squared norm of x: (1,0) and (0,1) both give 1 squared plus 0 squared equal to 1, so the sum of squares itself is invariant under orthogonal rotation. But the linear term can differ: if a equals (1,0), the scores of the two points are b plus 1 plus c and b plus c, not equal. The historical architecture: the source describes three hidden layers, the first two made of feature maps; each unit sees only a local window of the previous layer and corresponding connections on one map share weights. This is the same sharing principle as the three-cell stroke of this example but not the same architecture; without enough original detail its full parameter count or accuracy cannot be derived (computed by program)."),
    ("Square-term model v = b + sum a_i x_i + c sum x_i^2: points (1,0) and (0,1) both have sum of squares 1, but with a=(1,0) the scores b+1+c and b+c differ.",) * 2)
add(8, ("小練習", "Exercises"),
    ("兩題小練習：8×8 輸入得 6×6 特徵圖，不共享 360、共享 10 個參數；高分位置跟著移動是等變", "Exercises: an 8×8 input gives a 6×6 map, 360 parameters without sharing, 10 with it"),
    ("平方和對旋轉不變，但線性項讓整體不對稱。改變影像大小重新算一次參數，再分清等變與不變：答案是什麼？", "The sum of squares is rotation invariant but the linear term breaks the symmetry. Recount the parameters for another image size and then tell equivariance from invariance: what are the answers?"),
    ("兩題小練習。題 1：8×8 輸入、3×3 視窗、步長 1、不補邊，偏置也共享，特徵圖多大？共享與不共享各有幾個參數？每個方向 8 減 3 加 1 等於 6 個位置，共 6 乘 6 等於 36，特徵圖為 6×6；不共享 36 乘 (9 加 1) 等於 360，共享 9 加 1 等於 10；影像變大只增加使用次數，不增加這一組共享參數。題 2：共享後，高分位置跟著輸入移動，這叫等變還是不變？比較 F(Tx) 等於 T F(x) 與 F(Tx) 等於 F(x)：高分位置跟著移動，是等變；再做適當的彙整且條件成立，才可能得到不變的特徵，本例最大值彙整後 z 都是 3（程式計算）。",
     "Two exercises. Q1: with an 8×8 input, a 3×3 window, stride 1, no padding and a shared bias, how large is the feature map and how many parameters with and without sharing? In each direction 8 minus 3 plus 1 equals 6 positions, 6 times 6 equals 36, so the map is 6×6; without sharing 36 times (9 plus 1) equals 360 and with sharing 9 plus 1 equals 10; a larger image only adds uses, not shared parameters. Q2: after sharing, the high-score position moves with the input; is that equivariance or invariance? Compare F(Tx) equal to T F(x) with F(Tx) equal to F(x): the high-score position moves, so it is equivariance; only with a suitable pooling and the conditions satisfied can invariant features arise, and in this example z is 3 after max pooling (computed by program)."),
    ("Exercise 1: 8x8 input gives a 6x6 map with 36 positions; 360 parameters without sharing, 10 with sharing. Exercise 2: the high-score position moves with the input, so it is equivariance.",) * 2)
add(9, ("精確式與邊界", "Exact formula"),
    ("延伸：共享視窗的精確式 r_ij = b + ΣΣ K_ac x_(i+a, j+c)，平移等變性在有限網格的邊界可能只在內部成立", "Extension: r_ij = b + ΣΣ K_ac x_(i+a, j+c); on a finite grid equivariance may hold only inside"),
    ("8×8 輸入得 6×6 特徵圖，不共享 360、共享 10 個參數；高分位置跟著移動是等變。窗口分數的精確式是什麼？在邊界又會怎樣？", "An 8×8 input gives a 6×6 map, 360 parameters without sharing and 10 with it. What is the exact window formula, and what happens at the boundary?"),
    ("這是延伸：共享視窗的精確式、邊界與梯度。令影像為 x、卷積核為 K、偏置為 b，採用不翻轉卷積核的互相關：r_ij 等於 b 加上 a 與 c 從 0 到 2 的 K_ac 乘 x_(i 加 a, j 加 c) 的總和；i、j 是視窗左上角位置，a、c 是核內的列、欄偏移，這裡用 c 避免與偏置 b 混淆。若有逐點活化 φ，特徵圖可取 F(x)_ij 等於 φ(r_ij)；主例子直接使用分數 r。有限網格的邊界：平移等變性的公式需要對應位置都合法；物件移出畫面、邊界補值不同，或平移量與步長不相容時，等式可能只在內部區域成立；影像旋轉也可能需要插值，單純相同長度的權重分組不能消除取樣誤差。共享梯度：J 對 k 的偏導等於各位置 J 對 r_p 的偏導乘 r_p 對 k 的偏導的總和，局部線性計分下第二個因子就是該位置的輸入 x_p。",
     "This is the extension: the exact shared-window formula, boundaries and the gradient. Let the image be x, the kernel K and the bias b, using cross-correlation, where the kernel is not flipped: r_ij equals b plus the sum over a and c from 0 to 2 of K_ac times x at (i plus a, j plus c); i, j is the top-left corner of the window and a, c are the row and column offsets inside the kernel, with c used to avoid a clash with the bias b. With a pointwise activation φ the feature map can be F(x)_ij equal to φ(r_ij); the main example uses the score r directly. Boundaries of a finite grid: the equivariance formula needs all corresponding positions to be valid; when an object leaves the frame, the padding differs, or the shift is incompatible with the stride, the equality may hold only in the interior; image rotation may also need interpolation, and grouping weights of equal length alone cannot remove sampling error. The shared gradient: the derivative of J with respect to k equals the sum over positions of the derivative of J with respect to r_p times the derivative of r_p with respect to k, and under local linear scoring the second factor is the input x_p at that position."),
    ("Left: the window formula r_ij = b + sum K_ac x_{i+a,j+c} and the chain rule for the shared gradient; right: three boundary cases of a finite grid (object leaves the frame, incompatible padding or stride, rotation needing interpolation).",) * 2)
PAGES = P
